/**
 * The public claim layer, as a component sees it.
 *
 * Reached through `import.meta.glob`, not `node:fs`, for the same reason
 * src/components/base/data.ts gives: a glob is resolved by Vite at transform
 * time, so a file that does not exist is simply absent from the map rather
 * than a path that resolves differently in dev and in build.
 *
 * Everything under src/data/claims/ is GENERATED by scripts/build_claims.mjs.
 * Files whose name begins with an underscore are not claims: `_manifest.json`
 * records how the generation ran, `_ui.json` carries the disclosure's own
 * labels. Both are filtered out here rather than by pattern in the glob, so a
 * new sidecar cannot silently become a claim.
 */
import { copy } from "../../copy";
import {
  claimProblems,
  requireValidClaim,
  technicalProvenance,
  OUTCOME_TO_STATUS,
  STATUS_TO_OUTCOME,
  PUBLIC_DISCLOSURE_FIELDS,
  findMachineId,
} from "./validate.mjs";
import type { PublicClaim } from "./types";

export type { PublicClaim, PublicClaimStatus, PublicClaimType } from "./types";
export {
  technicalProvenance,
  OUTCOME_TO_STATUS,
  STATUS_TO_OUTCOME,
  PUBLIC_DISCLOSURE_FIELDS,
  findMachineId,
};

const claimModules = import.meta.glob<{ default: unknown }>(
  "../../data/claims/*.json",
  { eager: true },
);

const basename = (path: string): string => path.slice(path.lastIndexOf("/") + 1);

/**
 * How the generator ran: the sources it read and the counts it emitted. The
 * gate reads this to check the adapter's own accounting rather than trusting
 * the file list.
 */
export interface ClaimManifest {
  generatedBy: string;
  sources: { file: string; records: number }[];
  counts: Record<string, number>;
  /** Evidence id to the claims generated from it. */
  byEvidenceId: Record<string, string[]>;
  /** Evidence id, then the field a chip binds, to the claim for that field. */
  byEvidenceField: Record<string, Record<string, string>>;
  /** The one claim a chip bound to this evidence id shows by default. */
  defaultForEvidenceId: Record<string, string>;
  outcomeMapping: Record<string, string>;
  unmappedOutcomes: { outcome: string; cards: string[] }[];
}

/**
 * The disclosure's own labels.
 *
 * HANDOFF.md §8 rule 1 forbids a build agent from inventing a user-facing
 * string, and copy.yaml carries no key for any of these: it has
 * `ui.provenance_open` ("Where this number came from") and nothing for the
 * secondary technical affordance. The generator emits the requested wording
 * here and this function PREFERS copy.yaml whenever the key exists, so the
 * moment the build lead adds `ui.claim_*` the site picks it up with no code
 * change. `scripts/checks/claims-public.mjs` records the pending keys in
 * reports/vacuous-gates.json for as long as the fallback is in use, which is
 * the only way a temporary string does not become a permanent one.
 */
export interface ClaimUi {
  pendingCopyKeys: { key: string; text: string }[];
  labels: Record<string, string>;
}

const sidecar = <T>(name: string): T | null => {
  for (const [path, mod] of Object.entries(claimModules)) {
    if (basename(path) === name) return (mod as { default: T }).default;
  }
  return null;
};

export const claimManifest = (): ClaimManifest | null =>
  sidecar<ClaimManifest>("_manifest.json");

let uiCache: Record<string, string> | null = null;

/**
 * A disclosure label, from copy.yaml where the key exists and from the
 * generated fallback otherwise. The `ui` object is checked by dotted key so a
 * key that arrives later needs no code change here.
 */
export const claimLabel = (key: string): string => {
  if (!uiCache) {
    const file = sidecar<ClaimUi>("_ui.json");
    const fromCopy = (copy.ui ?? {}) as Record<string, unknown>;
    uiCache = {};
    for (const { key: k, text } of file?.pendingCopyKeys ?? []) {
      const short = k.startsWith("ui.") ? k.slice(3) : k;
      const live = fromCopy[short];
      uiCache[short] = typeof live === "string" && live.trim() !== "" ? live : text;
    }
    for (const [k, v] of Object.entries(file?.labels ?? {})) {
      if (!(k in uiCache)) uiCache[k] = v;
    }
  }
  const short = key.startsWith("ui.") ? key.slice(3) : key;
  const value = uiCache[short];
  if (value === undefined) {
    throw new Error(
      `claimLabel("${key}"): no such label. Labels come from copy.yaml when the key ` +
        `exists and from src/data/claims/_ui.json otherwise, and both are generated. ` +
        `Add the key to the adapter, never to a component.`,
    );
  }
  return value;
};

/** Which of the requested keys are still falling back to the generated text. */
export const pendingCopyKeys = (): { key: string; text: string }[] => {
  const file = sidecar<ClaimUi>("_ui.json");
  const fromCopy = (copy.ui ?? {}) as Record<string, unknown>;
  return (file?.pendingCopyKeys ?? []).filter(({ key }) => {
    const short = key.startsWith("ui.") ? key.slice(3) : key;
    const live = fromCopy[short];
    return !(typeof live === "string" && live.trim() !== "");
  });
};

let cache: Map<string, PublicClaim> | null = null;

const load = (): Map<string, PublicClaim> => {
  if (cache) return cache;
  const map = new Map<string, PublicClaim>();
  const problems: string[] = [];
  for (const [path, mod] of Object.entries(claimModules)) {
    const name = basename(path);
    if (name.startsWith("_")) continue;
    const claim = (mod as { default: PublicClaim }).default;
    problems.push(...claimProblems(claim, `src/data/claims/${name}`));
    if (claim && claim.slug) {
      if (map.has(claim.slug)) {
        problems.push(
          `src/data/claims/${name}: slug "${claim.slug}" is already claimed by another file. ` +
            `A slug is the import key and it has to be unique.`,
        );
      }
      if (`${claim.slug}.json` !== name) {
        problems.push(
          `src/data/claims/${name}: slug "${claim.slug}" does not match its filename. ` +
            `The adapter writes one file per slug so a claim can be found without an index.`,
        );
      }
      map.set(claim.slug, claim);
    }
  }
  if (problems.length) {
    throw new Error(
      `The generated public claims do not validate:\n  ${problems.join("\n  ")}\n` +
        `Regenerate with \`npm run build:claims\`; never edit a file under src/data/claims/.`,
    );
  }
  cache = map;
  return map;
};

export const allClaims = (): readonly PublicClaim[] =>
  [...load().values()].sort((a, b) => a.slug.localeCompare(b.slug));

export const claimOrNull = (slug: string): PublicClaim | null => load().get(slug) ?? null;

/**
 * Resolve a claim or fail the build, naming the slug and what is available.
 * Same discipline as resolveEvidence(): an id that does not resolve is a build
 * failure, not a rendered blank.
 */
export const requireClaim = (slug: string, who: string): PublicClaim => {
  const found = load().get(slug);
  if (!found) {
    const all = [...load().keys()];
    const near = all.filter((s) => s.includes(slug) || slug.includes(s)).slice(0, 4);
    throw new Error(
      `${who}: claim "${slug}" does not resolve against src/data/claims/ (${all.length} claims). ` +
        (near.length ? `Did you mean ${near.join(", ")}? ` : "") +
        `A claim slug that does not resolve fails the build, naming the page and the slug.`,
    );
  }
  return requireValidClaim(found, who);
};

/**
 * The claim a provenance chip shows when it was given an evidence id and no
 * claim slug. This is what removes `campaign.adjudication.ADJ-AVP` from the
 * homepage: the chip had nothing else to show, and now it does.
 */
export const claimForEvidence = (evidenceId: string): PublicClaim | null => {
  const slug = claimManifest()?.defaultForEvidenceId?.[evidenceId];
  return slug ? (claimOrNull(slug) ?? null) : null;
};

/**
 * The claim for one field of one record, and whether it is that field's own or
 * the study's.
 *
 * `exact` is not cosmetic. A chip that fell back to the study's adjudication
 * is disclosing at a coarser grain than one bound to its own quantity, and the
 * panel renders the two differently rather than letting a study-level sentence
 * pass for a quantity-level one.
 */
export const claimForEvidenceField = (
  evidenceId: string,
  field: string,
): { claim: PublicClaim; exact: boolean } | null => {
  const manifest = claimManifest();
  const exactSlug = field ? manifest?.byEvidenceField?.[evidenceId]?.[field] : undefined;
  if (exactSlug) {
    const found = claimOrNull(exactSlug);
    if (found) return { claim: found, exact: true };
  }
  const fallback = claimForEvidence(evidenceId);
  return fallback ? { claim: fallback, exact: false } : null;
};

/** Every claim generated from one evidence record, in slug order. */
export const claimsForEvidence = (evidenceId: string): readonly PublicClaim[] => {
  const slugs = claimManifest()?.byEvidenceId?.[evidenceId] ?? [];
  return slugs
    .map((s) => claimOrNull(s))
    .filter((c): c is PublicClaim => c !== null)
    .sort((a, b) => a.slug.localeCompare(b.slug));
};

/**
 * The three sentences a normal disclosure renders, in reading order: where it
 * came from, what it ranges over, what it does not establish. No labels, no
 * machine ids, and nothing a visitor has to decode.
 */
export const publicDisclosure = (claim: PublicClaim): { key: string; text: string }[] =>
  PUBLIC_DISCLOSURE_FIELDS.map((key) => ({
    key,
    text: String((claim as unknown as Record<string, unknown>)[key] ?? ""),
  })).filter((row) => row.text.trim() !== "");
